import csv,re,datetime
from decimal import Decimal
ALIAS={"taxi":"Travel","uber":"Travel","flight":"Travel","hotel":"Lodging","airbnb":"Lodging","lunch":"Meals","dinner":"Meals","coffee":"Meals","saas":"Software","software":"Software","license":"Software","books":"Learning","course":"Learning"}
MON={m:i for i,m in enumerate("jan feb mar apr may jun jul aug sep oct nov dec".split(),1)}
def pd(s):
    s=s.strip()
    if m:=re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})",s): y,mo,d=m.groups()
    elif m:=re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})",s): mo,d,y=m.groups()
    elif m:=re.fullmatch(r"(\d{1,2}) ([A-Za-z]{3})\w* (\d{4})",s): d,mo,y=m.groups(); mo=MON[mo.lower()[:3]]
    else: raise ValueError(s)
    return datetime.date(int(y),int(mo),int(d))
seen=set(); cats={}; flags=[]; total=Decimal(0); rows=[]
for r in csv.DictReader(open("expenses.csv",newline="")):
    if r["id"] in seen: continue
    seen.add(r["id"])
    d=pd(r["date"])
    if (d.year,d.month)!=(2026,10) or r["status"].strip().lower()=="void": continue
    amt=Decimal(re.sub(r"USD|\$|,|\s","",r["amount"]))
    cat=ALIAS[r["category"].strip().lower()]
    n,s=cats.get(cat,(0,Decimal(0))); cats[cat]=(n+1,s+amt); total+=amt
    rows.append((int(r["id"]),d,cat,amt))
print("total",total,"count",sum(n for n,_ in cats.values()))
for k,(n,s) in sorted(cats.items(),key=lambda kv:(-kv[1][1],kv[0])): print(k,n,s)
print("flags",[(i,str(a)) for i,d,c,a in rows if a>500])
print("oct rows",sorted(rows))
EOF", "description": "Independently verify report totals"}

